begin;
create extension if not exists pgtap with schema extensions;
select plan(20);
insert into auth.users(id,aud,role,email,created_at,updated_at) values('16400000-0000-4000-8000-000000000010','authenticated','authenticated','end-date-manager@example.test',now(),now());
insert into public.profiles(id,role,full_name,is_active) values('16400000-0000-4000-8000-000000000010','academic_manager','TEST-END-MANAGER',true);
select set_config('request.jwt.claims','{"sub":"16400000-0000-4000-8000-000000000010","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into public.b2c_classes(id,program_slug,name,start_date,capacity) values('16400000-0000-4000-8000-000000000001','tieng-anh','TEST-END-CLASS','2026-10-01',10)$$,'Create class without optional end date');
select ok((select end_date is null from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'),'Unknown end date stays null');
select throws_ok($$insert into public.b2c_classes(program_slug,name,start_date,end_date) values('tieng-anh','TEST-END-INVALID','2026-10-01','2026-09-30')$$,'23514',null,'DB rejects end before opening');
select lives_ok($$insert into public.b2c_classes(id,program_slug,name,start_date,end_date) values('16400000-0000-4000-8000-000000000002','tieng-anh','TEST-END-SAME','2026-10-01','2026-10-01')$$,'Same-day course permitted');
select lives_ok($$insert into public.b2c_classes(id,program_slug,name,end_date) values('16400000-0000-4000-8000-000000000003','tieng-anh','TEST-END-ONLY','2026-12-31')$$,'End may be recorded when opening is unknown');
select set_config('test.class_data','{"name":"TEST-END-CLASS","program_slug":"tieng-anh","capacity":10,"campus":"","delivery_mode":"offline","start_date":"2026-10-01","end_date":"2026-12-31","status":"active","notes":""}',true);
select lives_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb,'16400000-0000-4000-8000-000000000020',(select updated_at from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'))$$,'Manager edits existing class without personal B2C teacher link');
select is((select end_date::text from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'),'2026-12-31','End date persisted');
select is(public.read_teacher_b2c_class_edit('16400000-0000-4000-8000-000000000001')->>'end_date','2026-12-31','Edit projection exposes end date');
select is(public.read_teacher_b2c_workspace('16400000-0000-4000-8000-000000000001','students',0,'',null)->'class'->>'end_date','2026-12-31','Scoped workspace projection exposes end date');
select lives_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb,'16400000-0000-4000-8000-000000000020',null)$$,'Exact request retry remains safe');
select is((select count(*)::integer from public.b2c_class_history where class_id='16400000-0000-4000-8000-000000000001' and action='save_class'),1,'Retry creates no duplicate history');
select is((select after_data->>'end_date' from public.b2c_class_history where class_id='16400000-0000-4000-8000-000000000001' and action='save_class'),'2026-12-31','Date included in audit snapshot');
select throws_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb||'{"end_date":"2027-01-01"}','16400000-0000-4000-8000-000000000020',null)$$,'P0001',null,'Changed reused request rejected');
select throws_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb,'16400000-0000-4000-8000-000000000021','2000-01-01')$$,'40001',null,'Stale edit rejected');
select throws_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb||'{"end_date":"2026-09-30"}','16400000-0000-4000-8000-000000000022',(select updated_at from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'))$$,'23514',null,'Invalid edit rejected atomically');
select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb-'end_date','16400000-0000-4000-8000-000000000023',(select updated_at from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'));
select is((select end_date::text from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'),'2026-12-31','Legacy payload does not clear date');
select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb||'{"end_date":""}','16400000-0000-4000-8000-000000000024',(select updated_at from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'));
select ok((select end_date is null from public.b2c_classes where id='16400000-0000-4000-8000-000000000001'),'Explicit blank clears optional date');
select throws_ok($$select public.save_teacher_b2c_class(null,current_setting('test.class_data')::jsonb,'16400000-0000-4000-8000-000000000025',null)$$,'42501',null,'Teacher self-creation still needs linked teacher');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.read_teacher_b2c_class_edit('16400000-0000-4000-8000-000000000001')$$,'42501',null,'Unprivileged read blocked');
select throws_ok($$select public.save_teacher_b2c_class('16400000-0000-4000-8000-000000000001',current_setting('test.class_data')::jsonb,'16400000-0000-4000-8000-000000000026',null)$$,'42501',null,'Unprivileged edit blocked');
select * from finish();
rollback;
